import{_ as d,C as n,o as l,c as i,j as t,a as s,E as a,a2 as p}from"./chunks/framework.CtQGab4e.js";const f=JSON.parse('{"title":"Hoe de tool denkt","description":"","frontmatter":{},"headers":[],"relativePath":"plattegrond/hoe-de-tool-denkt.md","filePath":"plattegrond/hoe-de-tool-denkt.md"}'),g={name:"plattegrond/hoe-de-tool-denkt.md"};function h(k,e,m,u,v,c){const r=n("ModelDiagram"),o=n("Media");return l(),i("div",null,[e[0]||(e[0]=t("h1",{id:"hoe-de-tool-denkt",tabindex:"-1"},[s("Hoe de tool denkt "),t("a",{class:"header-anchor",href:"#hoe-de-tool-denkt","aria-label":'Permalink to "Hoe de tool denkt"'},"​")],-1)),e[1]||(e[1]=t("p",null,"De teken-tool lijkt op een tekenprogramma, maar hij werkt anders. Je tekent geen plaatje, je beschrijft een gebouw. Uit die beschrijving maakt de 3D-server een 3D-model en rekent hij de oppervlaktes uit.",-1)),a(r),e[2]||(e[2]=p('<h2 id="muren-zijn-geen-lijnen" tabindex="-1">Muren zijn geen lijnen <a class="header-anchor" href="#muren-zijn-geen-lijnen" aria-label="Permalink to &quot;Muren zijn geen lijnen&quot;">​</a></h2><p>Een muur is een lijnstuk met twee uiteinden. Raken twee muren elkaar in een hoekpunt, dan zitten ze aan elkaar vast. Dat is het verschil met een tekenprogramma: de tool weet welke muren met elkaar verbonden zijn. Sleep je een hoekpunt, dan gaan de muren eraan mee.</p><p>Muren zijn altijd zwart. Kleur speelt geen rol; wat een muur <em>is</em>, stel je in met eigenschappen.</p><h2 id="ruimtes-ontstaan-vanzelf" tabindex="-1">Ruimtes ontstaan vanzelf <a class="header-anchor" href="#ruimtes-ontstaan-vanzelf" aria-label="Permalink to &quot;Ruimtes ontstaan vanzelf&quot;">​</a></h2><p>Elke gesloten ring van muren is een <strong>vlak</strong>. Je tekent dus geen ruimtes, je tekent muren, en de ruimtes volgen. Een muur dwars door een vlak deelt het in tweeën.</p><p>Is een ring niet helemaal dicht, dan is er geen vlak. Dat is de meest voorkomende reden dat een ruimte &quot;niet werkt&quot;, zie de <a href="./../faq.html">veelgestelde vragen</a>.</p><h2 id="eigenschappen-op-de-muur-of-op-het-vlak" tabindex="-1">Eigenschappen: op de muur of op het vlak <a class="header-anchor" href="#eigenschappen-op-de-muur-of-op-het-vlak" aria-label="Permalink to &quot;Eigenschappen: op de muur of op het vlak&quot;">​</a></h2><p>Elke eigenschap hoort bij een muur of bij een vlak. Dat volgt uit wat hij beschrijft:</p><table tabindex="0"><thead><tr><th>Hoort bij</th><th>Eigenschap</th><th>Waarom daar</th></tr></thead><tbody><tr><td>Vlak</td><td>Installaties (verwarming, koeling)</td><td>Een ruimte wordt verwarmd, niet een muur.</td></tr><tr><td>Vlak</td><td>Eigenschap: gebruiksoppervlak, &lt;1,5m, niet berekend</td><td>Bepaalt of de m² meetellen.</td></tr><tr><td>Vlak</td><td>Plat dak</td><td>Een plat dak ligt boven een stuk plattegrond.</td></tr><tr><td>Muur</td><td>Begrenzing: buiten, buren, onverwarmd, sterk geventileerd</td><td>Een gevel grenst ergens aan.</td></tr><tr><td>Muur</td><td>Isolatie</td><td>Een afwijkend geïsoleerde gevel.</td></tr><tr><td>Muur</td><td>Dak: goothoogte en daklagen</td><td>Een hellend dak begint bij een gevel.</td></tr></tbody></table><p>Daarom tik je een <strong>vlak</strong> aan voor een plat dak, maar selecteer je een <strong>muur</strong> voor een hellend dak.</p><h2 id="verdiepingen-liggen-naast-elkaar" tabindex="-1">Verdiepingen liggen naast elkaar <a class="header-anchor" href="#verdiepingen-liggen-naast-elkaar" aria-label="Permalink to &quot;Verdiepingen liggen naast elkaar&quot;">​</a></h2><p>Alle verdiepingen staan in dezelfde notitie, naast elkaar op het canvas. Elke verdieping krijgt in <strong>Eigenschappen</strong> een hoogte en een gekoppelde hoek (het referentiepunt). De 3D-server stapelt de verdiepingen op elkaar door die hoeken op elkaar te leggen.</p><p>Een aanbouw met andere hoogtes is een <strong>gebouwdeel</strong>: een eigen tabblad bij de hoogtes, dat je in de vlak-popup aan ruimtes toewijst.</p><h2 id="wat-de-3d-server-ermee-doet" tabindex="-1">Wat de 3D-server ermee doet <a class="header-anchor" href="#wat-de-3d-server-ermee-doet" aria-label="Permalink to &quot;Wat de 3D-server ermee doet&quot;">​</a></h2><p>Tik je in het <a href="./3d-paneel.html">3D-paneel</a> op <strong>Genereer</strong>, dan gaan de muren, vlakken, hoogtes en alle eigenschappen naar de 3D-server. Die maakt daarvan wanden, vloeren en daken, en rekent per gevel, dak en vloer de m² uit, gesplitst naar begrenzing, oriëntatie en isolatie. Die m² controleer en corrigeer je daarna in het paneel, zie <a href="./constructies.html">Constructies en correcties</a>.</p><p>De details per onderdeel: <a href="./muren.html">muren</a>, <a href="./vlakken.html">vlakken</a>, <a href="./installaties.html">installaties</a> en <a href="./gebouw.html">gebouweigenschappen</a>.</p>',16)),a(o,{todo:"Afbeelding: dezelfde woning naast elkaar als plattegrond in de teken-tool en als 3D-model."})])}const j=d(g,[["render",h]]);export{f as __pageData,j as default};
